/**
 * The publish panel's text rules, with no React. The metadata and its rows
 * are generated by the server (SUMTAB-08).
 */
import type { MetadataRowResponse, PublicationSendResponse } from "@/client"
import { telegramWebBaseUrl } from "@/lib/telegram-web"

export const partsLabel = (n: number) => `${n} message${n === 1 ? "" : "s"}`

/** What a send's answer tells the publisher. */
export function publicationToast(result: PublicationSendResponse): {
  kind: "success" | "error"
  text: string
} {
  if (result.status === "success")
    return {
      kind: "success",
      text: `Published ${partsLabel(result.partsTotal)}.`,
    }
  return {
    kind: "error",
    text: `Publishing stopped after ${result.partsSent} of ${partsLabel(result.partsTotal)}: ${result.error}`,
  }
}

/** The rows to leave out once `key` is ticked or unticked. */
export function omittedAfterToggle(
  rows: MetadataRowResponse[],
  key: string,
): string[] {
  return rows
    .filter((r) => (r.key === key ? r.sent : !r.sent))
    .map((r) => r.key)
}

export type TelegramSegment =
  | { kind: "plain" | "bold" | "italic"; text: string }
  | { kind: "link"; text: string; url: string }

/** The server's entity pattern (`network.py`): `**b**`, `*i*`, `_i_`, a Citation, `[text](url)`. */
const MARKUP =
  /(\*\*(.*?)\*\*)|(\*(.*?)\*)|(_(.*?)_)|(\[([a-zA-Z0-9_]+)\s+#(\d+)\])|(\[(.*?)\]\((.*?)\))/g

function segment(m: RegExpMatchArray): TelegramSegment {
  if (m[1]) return { kind: "bold", text: m[2] }
  if (m[3] || m[5]) return { kind: "italic", text: m[4] ?? m[6] }
  if (m[7])
    return {
      kind: "link",
      text: m[7],
      url: `${telegramWebBaseUrl()}/${m[8]}/${m[9]}`,
    }
  return { kind: "link", text: m[11], url: m[12] }
}

/** A Part's text as Telegram shows it: plain runs and formatted ones. */
export function telegramSegments(text: string): TelegramSegment[] {
  const out: TelegramSegment[] = []
  let last = 0
  for (const m of text.matchAll(MARKUP)) {
    const at = m.index ?? 0
    if (at > last) out.push({ kind: "plain", text: text.slice(last, at) })
    out.push(segment(m))
    last = at + m[0].length
  }
  if (last < text.length) out.push({ kind: "plain", text: text.slice(last) })
  return out
}
